import{z as n,x as i,o as A,c as p,q as l,j as r,D as a,d as e,s as o,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"延迟与成本优化","description":"","frontmatter":{"title":"延迟与成本优化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-latency-cost.md","filePath":"llm/rag-latency-cost.md","lastUpdated":1791063341000}'),d={name:"llm/rag-latency-cost.md"};function C(m,E,D,c,h,F){const t=i("Mermaid");return A(),p("div",null,[E[2]||(E[2]=l('<h1 id="延迟与成本优化" tabindex="-1">延迟与成本优化 <a class="header-anchor" href="#延迟与成本优化" aria-label="Permalink to &quot;延迟与成本优化&quot;">​</a></h1><div class="epigraph"><p>链路上的段量级不同：把近邻从二十毫秒压到十毫秒，用户毫无感觉；把上下文砍掉一半，账单立刻看见。优化的第一步是分段测量，不是动手。</p><footer>—— 据推理成本模型与检索工程实践整理</footer></div><p><a href="/llm/RAG-eval-triangle">上一课</a>立了三角门禁：任何优化都要过三角，单角大涨先查代价藏在哪。本课写优化本身：一条 RAG 查询的时间与钱花在哪几段、砍哪里不伤质量、缓存与条件执行怎么设计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链路各段的量级不同：查询嵌入与 ANN 在毫秒与亚毫秒级，改写与规划是一次 LLM 往返（几百毫秒），重排是几十到几百毫秒的 GPU 前向，生成段是秒级且占成本大头。不先测量就优化的两种典型：把 ANN 从二十毫秒压到十毫秒，端到端无感，白付一次工程；或者砍掉重排省钱，前排精度掉，三角门禁阻断——又回滚。更隐蔽的是成本侧：检索段的自建成本（索引内存、批处理 GPU）是固定开销，生成段随答案长度线性，两者的容量规划逻辑完全不同，混在一个「单查询成本」里就找错了杠杆。</p><p><span class="marginnote">术语翻译：TTFT 是「首字时间」——从发问到屏幕上吐出第一个字，用户感知的「快不快」主要是它；TPOT 是「每字时间」——首字之后每个 token 的平均间隔，决定阅读时顺不顺。生成段占延迟大头，指的就是这两项，而它们都随输入长度变长而变差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分段测量先立住：p50、p95、p99 每段分开报，嵌入、ANN、融合、重排、生成 TTFT 与 TPOT 各一列；成本按推理成本模型的口径——租时除以有效吞吐，加利用率与重试，提示与生成分列。然后三个杠杆按序动。第一，条件执行：第六课的复杂度路由本来就是预算工具——简单查询跳过改写与重排，直接单次检索；只有困难切片走全链，多数流量付多数场景需要的钱。第二，缓存三层：块向量与查询嵌入缓存（语料不变即有效）、检索结果缓存（查询归一化后命中）、生成侧前缀缓存（系统提示与块模板预计算，<a href="/llm/prompt-cache">Prompt Cache</a> 的模块化口径；块顺序稳定是复用前提，重排恰好保证这点）。第三，粗到细与压缩：<a href="/llm/matryoshka-embeddings">Matryoshka</a> 短前缀粗召回加全维精排，省 ANN 时间；上下文压缩（<a href="/llm/rag-context-compression">RAG 压缩</a>）直接砍生成段的输入 token，这是成本大头上的杠杆。</p><p><span class="marginnote">数字实例：压缩杠杆有多值钱——输入 4000 token、输出 400 token 的查询，输入占九成计费量；上下文压缩砍掉七成输入，单查询成本立刻从约 4400 token 降到约 1600 token，超过六成账单直接消失。相比之下把 ANN 从 20 ms 压到 10 ms，账单一个字都不会变。</span></p>',9)),(A(),r(s,null,{default:a(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEAS%5B%22%E5%88%86%E6%AE%B5%E6%B5%8B%E9%87%8F%EF%BC%9A%E5%BB%B6%E8%BF%9F%E4%B8%8E%E6%88%90%E6%9C%AC%E5%90%84%E5%88%97%22%5D%20--%3E%20R1%7B%22%E6%9D%A1%E4%BB%B6%E6%89%A7%E8%A1%8C%EF%BC%9A%E7%AE%80%E5%8D%95%E6%9F%A5%E8%AF%A2%EF%BC%9F%22%7D%0A%20%20R1%20--%3E%7C%E6%98%AF%7C%20FAST%5B%22%E8%B7%B3%E8%BF%87%E6%94%B9%E5%86%99%E4%B8%8E%E9%87%8D%E6%8E%92%22%5D%0A%20%20R1%20--%3E%7C%E5%90%A6%7C%20FULL%5B%22%E5%85%A8%E9%93%BE%EF%BC%9A%E6%94%B9%E5%86%99%20%2B%20%E9%87%8D%E6%8E%92%22%5D%0A%20%20FAST%20--%3E%20CACHE%5B%22%E4%B8%89%E5%B1%82%E7%BC%93%E5%AD%98%EF%BC%9A%E5%B5%8C%E5%85%A5%20%2F%20%E7%BB%93%E6%9E%9C%20%2F%20%E5%89%8D%E7%BC%80%22%5D%0A%20%20FULL%20--%3E%20CACHE%0A%20%20CACHE%20--%3E%20CUT%5B%22%E7%B2%97%E5%88%B0%E7%BB%86%20%2B%20%E4%B8%8A%E4%B8%8B%E6%96%87%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20CUT%20--%3E%20TRI%5B%22%E8%BF%87%E4%B8%89%E8%A7%92%E9%97%A8%E7%A6%81%22%5D%0A%20%20TRI%20--%3E%20KEEP%7B%22%E8%B4%A8%E9%87%8F%E4%B8%8D%E6%8E%89%EF%BC%9F%22%7D%0A%20%20KEEP%20--%3E%7C%E6%98%AF%7C%20SHIP%5B%22%E4%BF%9D%E7%95%99%E4%BC%98%E5%8C%96%22%5D%0A%20%20KEEP%20--%3E%7C%E5%90%A6%7C%20ROLL%5B%22%E5%9B%9E%E6%BB%9A%E8%AF%A5%E9%A1%B9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"缓存在 RAG 为什么特别有效：查询高度重复——FAQ 型流量里头部查询占比可观，块向量与块文本天然可缓存且不变；前缀缓存要块顺序稳定，重排后的顺序是确定性的，反而成了复用条件。条件执行为什么可行：查询难度分布长尾，多数是单跳直答型，为百分之几的难查询让全部流量付全链延迟，是错配。压缩为什么动的是大头：生成段计费与延迟都随输入加输出 token 走，检索段的毫秒级优化在秒级面前不显眼——但这不意味着检索侧可以烂，检索烂了忠实度掉，门禁会拦住。每一项优化单独上、单独过三角：多项一起上，回退时说不清是谁伤了质量。",-1)),(A(),r(s,null,{default:a(()=>[o(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20SEG%5B%22RAG%20%E4%B8%80%E6%AC%A1%E6%9F%A5%E8%AF%A2%E7%9A%84%E5%88%86%E6%AE%B5%22%5D%20--%3E%20EMB%5B%22%E5%B5%8C%E5%85%A5%2BANN%3A%20%E6%AF%AB%E7%A7%92%E7%BA%A7%22%5D%0A%20%20SEG%20--%3E%20RR%5B%22%E6%94%B9%E5%86%99%2B%E9%87%8D%E6%8E%92%3A%20%E5%87%A0%E5%8D%81%E5%88%B0%E5%87%A0%E7%99%BE%E6%AF%AB%E7%A7%92%22%5D%0A%20%20SEG%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%3A%20%E7%A7%92%E7%BA%A7%2C%20%E6%88%90%E6%9C%AC%E5%A4%A7%E5%A4%B4%22%5D%0A%20%20EMB%20--%3E%20L1%5B%22%E6%9D%A0%E6%9D%86%3A%20Matryoshka%20%E7%B2%97%E5%8F%AC%E5%9B%9E%22%5D%0A%20%20RR%20--%3E%20L2%5B%22%E6%9D%A0%E6%9D%86%3A%20%E6%9D%A1%E4%BB%B6%E6%89%A7%E8%A1%8C%E8%B7%B3%E8%BF%87%22%5D%0A%20%20GEN%20--%3E%20L3%5B%22%E6%9D%A0%E6%9D%86%3A%20%E4%B8%8A%E4%B8%8B%E6%96%87%E5%8E%8B%E7%BC%A9%E7%A0%8D%E8%BE%93%E5%85%A5%22%5D%0A%20%20L1%20--%3E%20GATE%5B%22%E5%88%86%E6%AE%B5%E6%B5%8B%E9%87%8F%20%2B%20%E4%B8%89%E8%A7%92%E9%97%A8%E7%A6%81%22%5D%0A%20%20L2%20--%3E%20GATE%0A%20%20L3%20--%3E%20GATE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">常见误区：初学者只看 p50（一半请求比它快）就说「平均 800 毫秒，够快」。用户体验由长尾决定——p99 的那 1% 请求可能要 8 秒，正好是最重要或最复杂的查询撞上。分段测量必须三档都报，优化瞄准的是 p99，不是均值。</span></p><p><span class="marginnote">缓存有正确性面：不同权限用户共享检索结果缓存会跨租户泄漏；缓存键必须带权限范围。这一条与增量更新课的删除同步是同一类问题——性能优化改动了安全边界。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>条件执行的路由错误由第六课的回退兜住，但降级路径的延迟与质量也要进评测。压缩率不是指标：压缩到忠实度掉线，省的钱赔进错误答案。前缀缓存对块顺序敏感，重排策略换版即缓存全失效，失效风暴要算进发布成本。成本模型别假设无限线性扩展：容量墙之上排队延迟接管曲线，见成本模型课的容量口径。每查询的钱和时间都进了账本之后，还剩一个时间维度：语料天天变，索引怎么跟上——增量更新与一致性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先分段测量再动手：p50 与 p99 每段一列，成本提示与生成分列。</li><li>杠杆按序：条件执行、三层缓存、粗到细与上下文压缩；大头在生成段。</li><li>每项优化单独过三角门禁；回滚要有版本，混着上说不清。</li><li>缓存键带权限范围；块顺序稳定是前缀复用的前提。</li><li>压缩率与延迟不是指标，忠实度不掉才是约束。</li><li>出处：据 Pope 等推理成本口径、Gim 等 Prompt Cache 与检索工程实践整理。</li></ul>',6))])}const _=n(d,[["render",C]]);export{f as __pageData,_ as default};
